Bytes ScriptSession::encodeMilitia(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=16u*1024u*1024u;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || (!units_.empty() && !encodeHandle) || units_.size()>65536)throw std::runtime_error("Militia snapshot requires a quiescent local session");std::map<std::uint32_t,const UnitState*> ordered;std::map<std::uint32_t,std::uint32_t> forward,reverse;auto mapped=[&](std::uint32_t id){auto key=encodeHandle("unit",id);auto [a,inserted]=forward.emplace(id,key);auto [b,unique]=reverse.emplace(key,id);if(!id || !key || (!inserted && a->second!=key) || (!unique && b->second!=id))throw std::runtime_error("Invalid militia unit mapping");return key;};for(auto& [id,u]:units_)ordered.emplace(mapped(id),u.get());SnapshotWriter out(budget-64);out.u32(tag("SMLT"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.size(ordered.size());for(auto [key,u]:ordered){out.u32(key);out.u32(u->militiaBell);out.u32(u->ignoreAlarm);out.u32(u->militia.has_value());if(u->militia){auto& m=*u->militia;auto hall=m.hall?mapped(m.hall):0;if(!hall || m.hall<handleBase || m.hall-handleBase>=objects_.size() || objects_[m.hall-handleBase].kind!=NativeKind::Unit || unsigned(m.phase)>unsigned(MilitiaState::Phase::ToWorker) || !m.ability || !m.workerType || !m.militiaType || !std::isfinite(m.remaining) || !std::isfinite(m.repath))throw std::runtime_error("Invalid militia state");out.u32(unsigned(m.phase));out.u32(hall);out.u32(m.ability);out.u32(m.workerType);out.u32(m.militiaType);out.u64(std::bit_cast<std::uint64_t>(m.remaining));out.u64(std::bit_cast<std::uint64_t>(m.repath));}}return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreMilitia(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    constexpr size_t budget=16u*1024u*1024u;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || militiaRestored_ || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event))throw std::runtime_error("Militia restore requires completed unit core before events");Binary in(openSnapshot(bytes,budget));in.expect(tag("SMLT"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Militia snapshot map or clock differs");auto count=in.count(16,65536);if(count!=units_.size() || (count && !decodeHandle))throw std::runtime_error("Militia unit count differs");auto flag=[&](){auto value=in.u32();if(value>1)throw std::runtime_error("Invalid militia flag");return value!=0;};auto unit=[&](std::uint32_t key){auto id=decodeHandle("unit",key);if(!key || !id || !unitIdentityHandles_.contains(key) || unitIdentityHandles_.at(key)!=id)throw std::runtime_error("Invalid militia reference mapping");return id;};struct Saved{std::uint32_t id;bool bell,alarm;std::optional<MilitiaState> state;};std::vector<Saved> pending;pending.reserve(count);std::set<std::uint32_t> seen;for(unsigned i=0;i<count;++i){auto id=unit(in.u32());if(!seen.insert(id).second || !alive(id,NativeKind::Unit) || !units_.contains(id))throw std::runtime_error("Invalid militia unit");Saved saved{id,flag(),flag(),{}};if(flag()){MilitiaState m;auto phase=in.u32();m.hall=unit(in.u32());m.ability=in.u32();m.workerType=in.u32();m.militiaType=in.u32();m.remaining=std::bit_cast<double>(snapshotU64(in));m.repath=std::bit_cast<double>(snapshotU64(in));if(phase>unsigned(MilitiaState::Phase::ToWorker) || !m.ability || !m.workerType || !m.militiaType || !std::isfinite(m.remaining) || !std::isfinite(m.repath))throw std::runtime_error("Invalid militia state");m.phase=MilitiaState::Phase(phase);saved.state=m;}pending.push_back(saved);}in.finish();for(auto& v:pending){auto& u=*units_.at(v.id);u.militiaBell=v.bell;u.ignoreAlarm=v.alarm;u.militia=v.state;}militiaRestored_=true;
}

void ScriptSession::cancelMilitiaOrder(UnitState& u){
    if(!u.militia || u.militia->phase==MilitiaState::Phase::None)return;
    if(u.militia->phase==MilitiaState::Phase::ToWorker && u.type==u.militia->militiaType)u.militia->phase=MilitiaState::Phase::None;
    else u.militia.reset();
}

bool ScriptSession::militiaCommand(std::uint32_t id,bool returning,std::uint32_t order){
    if(!alive(id,NativeKind::Unit))return false;auto u=units_.at(id);auto ability=sourceAbility(*u,"Amil");if(!ability.first || u->owner>=config_.players.size())return false;auto available=config_.players[u->owner].abilityAvailable.find(ability.first);if(available!=config_.players[u->owner].abilityAvailable.end() && !available->second)return false;auto spell=spellInfo(ability.first,ability.second);
    if(u->removing || u->paused || u->stunned() || u->construction || u->unsummon || u->illusion || u->abilitiesDisabled() || number(u->life)<=0 || (u->hidden() && !u->gather.inside) || u->type!=(returning?spell.alternateType:spell.normalType))return false;
    std::uint32_t hall=0;float nearest=std::numeric_limits<float>::infinity();for(auto& [candidate,building]:units_){if(building->owner!=u->owner || building->removing || building->hidden() || building->construction || number(building->life)<=0 || !unitClassContains(building->classifications(definitions().unitClasses(building->type)),"townhall"))continue;float distance=std::hypot(number(building->x)-number(u->x),number(building->y)-number(u->y));if(distance<nearest){nearest=distance;hall=candidate;}}
    if(!hall)return false;auto owner=u->owner;auto ownerRevision=u->ownerRevision,deathRevision=u->deathRevision;double remaining=u->militia?u->militia->remaining:spell.duration;if(!cancelCombat(*u) || !alive(id,NativeKind::Unit) || units_.at(id)!=u || u->owner!=owner || u->ownerRevision!=ownerRevision || u->deathRevision!=deathRevision || number(u->life)<=0 || !alive(hall,NativeKind::Unit) || units_.at(hall)->owner!=owner)return false;
    MilitiaState state;state.phase=returning?MilitiaState::Phase::ToWorker:MilitiaState::Phase::ToMilitia;state.hall=hall;state.ability=ability.first;state.workerType=spell.normalType;state.militiaType=spell.alternateType;state.remaining=remaining;u->militia=state;u->route.clear();u->waypoint=0;u->holding=false;u->currentOrder=order?order:(returning?spell.unorder:spell.order);auto revision=u->combat.revision;ScriptContext context;context.issuedOrder=u->currentOrder;unitEvent(id,38,75,context);return alive(id,NativeKind::Unit) && units_.at(id)==u && u->owner==owner && u->ownerRevision==ownerRevision && u->deathRevision==deathRevision && u->combat.revision==revision && u->militia.has_value();
}

bool ScriptSession::militiaTownBell(std::uint32_t id,bool returning){
    if(!alive(id,NativeKind::Unit))return false;auto town=units_.at(id);auto ability=sourceAbility(*town,"Amic");if(!ability.first || town->owner>=config_.players.size() || town->removing || town->paused || town->stunned() || town->construction || town->hidden() || town->abilitiesDisabled() || number(town->life)<=0)return false;auto available=config_.players[town->owner].abilityAvailable.find(ability.first);if(available!=config_.players[town->owner].abilityAvailable.end() && !available->second)return false;auto spell=spellInfo(ability.first,ability.second);auto owner=town->owner;auto ownerRevision=town->ownerRevision,deathRevision=town->deathRevision;if(!cancelCombat(*town) || !alive(id,NativeKind::Unit) || units_.at(id)!=town || town->owner!=owner || town->ownerRevision!=ownerRevision || town->deathRevision!=deathRevision || number(town->life)<=0)return false;town->militiaBell=!returning;town->currentOrder=returning?spell.unorder:spell.order;auto revision=town->combat.revision;ScriptContext context;context.issuedOrder=town->currentOrder;unitEvent(id,38,75,context);if(!alive(id,NativeKind::Unit) || units_.at(id)!=town || town->owner!=owner || town->ownerRevision!=ownerRevision || town->deathRevision!=deathRevision || town->combat.revision!=revision || number(town->life)<=0)return false;town->currentOrder=0;if(!returning)queueSpellSound(ability.first,{town->x,town->y});
    std::vector<std::uint32_t> candidates;for(auto& [candidate,u]:units_)if(candidate!=id && u->owner==owner && std::hypot(number(u->x)-number(town->x),number(u->y)-number(town->y))<=spell.area)candidates.push_back(candidate);for(auto candidate:candidates){if(!alive(id,NativeKind::Unit) || units_.at(id)!=town || town->owner!=owner || town->ownerRevision!=ownerRevision || town->deathRevision!=deathRevision || town->combat.revision!=revision || town->militiaBell==returning || number(town->life)<=0)break;militiaCommand(candidate,returning);}return true;
}

void ScriptSession::militiaTick(double delta){
    std::vector<std::uint32_t> actors;for(auto& [id,u]:units_)if(u->militia)actors.push_back(id);for(auto id:actors){if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!u->militia)continue;if(u->removing || number(u->life)<=0){u->militia.reset();continue;}if(u->paused)continue;auto state=*u->militia;if(state.phase==MilitiaState::Phase::None){if(u->type!=state.militiaType){u->militia.reset();continue;}u->militia->remaining-=delta;if(u->militia->remaining<=0)militiaCommand(id,true);continue;}
        if(u->type!=(state.phase==MilitiaState::Phase::ToMilitia?state.workerType:state.militiaType)){u->militia.reset();continue;}auto stop=[&]{u->route.clear();u->waypoint=0;u->currentOrder=0;cancelMilitiaOrder(*u);};if(!alive(state.hall,NativeKind::Unit)){stop();continue;}auto hall=units_.at(state.hall);if(hall->owner!=u->owner || hall->removing || hall->hidden() || hall->construction || number(hall->life)<=0 || !unitClassContains(hall->classifications(definitions().unitClasses(hall->type)),"townhall")){stop();continue;}float range=std::max(64.f,u->collision+hall->collision+32.f);float distance=std::hypot(number(u->x)-number(hall->x),number(u->y)-number(hall->y));if(distance>range){if(simulationTime_>=state.repath){chase(*u,{hall->x,hall->y},std::max(0.f,range-8));if(u->militia)u->militia->repath=simulationTime_+.25;}continue;}
        auto owner=u->owner;auto ownerRevision=u->ownerRevision,deathRevision=u->deathRevision,revision=u->combat.revision;auto target=state.phase==MilitiaState::Phase::ToMilitia?state.militiaType:state.workerType;if(!changeUnitForm(id,target,0,false) || !alive(id,NativeKind::Unit) || units_.at(id)!=u || u->owner!=owner || u->ownerRevision!=ownerRevision || u->deathRevision!=deathRevision || u->combat.revision!=revision || !u->militia || u->militia->phase!=state.phase || u->militia->hall!=state.hall)continue;u->currentOrder=0;if(state.phase==MilitiaState::Phase::ToWorker)u->militia.reset();else {u->militia->phase=MilitiaState::Phase::None;u->militia->remaining=state.remaining;}
    }
}
